style.css:
@-moz-document domain("youtube.com") {
html,
body,
ytd-app {
    background: transparent !important;
}

ytd-app {
    background-image:
        linear-gradient(rgba(3, 8, 25, 0.2), rgba(3, 8, 25, 0.35)),
        url("https://i.ibb.co/4Z3rfC30/0d656af756fae5bd5e0a165a17b01b32.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
}

ytd-page-manager,
ytd-browse,
ytd-watch-flexy,
#primary,
#secondary {
    background: transparent !important;
}

#masthead-container,
#masthead,
#guide,
ytd-guide-renderer {
    background: rgba(5, 12, 35, 0.75) !important;
    backdrop-filter: blur(12px) !important;
}

ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {
    background: rgba(8, 18, 45, 0.4) !important;
    border-radius: 14px !important;
    padding: 6px !important;
}

#video-title,
.title,
ytd-channel-name {
    color: #f0f5ff !important;
}

#metadata-line {
    color: #b9c9e8 !important;
}

ytd-thumbnail,
#thumbnail {
    border-radius: 14px !important;
    overflow: hidden !important;
}

ytd-popup-container,
tp-yt-paper-dialog {
    background: rgba(7, 15, 38, 0.96) !important;
}
}
